[data-recursica-theme] .mat-mdc-tooltip.rec-tooltip.rec-tooltip-beak::after {
  content: "";
  position: absolute;
  width: calc(
    var(--recursica_ui-kit_components_tooltip_properties_beak-size) * 0.7071
  );
  height: calc(
    var(--recursica_ui-kit_components_tooltip_properties_beak-size) * 0.7071
  );
  background-color: var(
    --recursica_ui-kit_components_tooltip_properties_colors_background-color
  );
  transform: rotate(45deg);
}

[data-recursica-theme]
  .mat-mdc-tooltip-panel-below
