  top: calc(
    var(--recursica_ui-kit_components_tooltip_properties_beak-size) * -0.3536
  );
  left: 50%;
  margin-left: calc(
    var(--recursica_ui-kit_components_tooltip_properties_beak-size) * -0.3536
  );
}

